// Efekt ve arayüz sprite'ları (pixel art).
//   effects/fx.png (256×64):  satır 0 → toplanabilir simit 4 kare (20×20, dönme), parıltı 2 kare (7×7), tüy (6×10), damla (3×3)
//                             satır 1 (y=24) → halkalar: 4 kare beyaz (kıl payı) + 4 kare altın (toplama), 32×32
//   ui/icons.png (19 ikon × 16 px, 304×16): beyaz maskeler, arayüzde boyanır
'use strict';
const { Canvas, mix } = require('./lib');

const INK = '#22202c';
const SIMIT = ['#f4c07a', '#d08a40', '#9a5c26'], SES = '#fff4d6';

function pickupFrame(squash) {
  const c = new Canvas(20, 20), cx = 10, cy = 10, rx = 7.5 * squash, ry = 7.5;
  for (let y = 0; y < 20; y++) for (let x = 0; x < 20; x++) {
    const nx = (x + 0.5 - cx) / Math.max(0.8, rx), ny = (y + 0.5 - cy) / ry, d = nx * nx + ny * ny;
    const inner = ((x + 0.5 - cx) / Math.max(0.4, rx * 0.42)) ** 2 + ((y + 0.5 - cy) / (ry * 0.42)) ** 2;
    if (d <= 1 && (inner > 1 || squash < 0.3)) c.set(x, y, ny < -0.35 ? SIMIT[0] : ny > 0.4 || nx > 0.55 ? SIMIT[2] : SIMIT[1]);
  }
  if (squash > 0.5) for (const [dx, dy] of [[-5, -3], [0, -6], [5, -3], [6, 2], [-6, 2], [0, 6]]) c.set(Math.round(cx + dx * squash), cy + dy, SES);
  c.outline(INK);
  return c;
}
function sparkle(big) {
  const c = new Canvas(7, 7), col = '#fff4c0';
  c.vline(3, big ? 0 : 1, big ? 6 : 5, col); c.hline(big ? 0 : 1, big ? 6 : 5, 3, col); c.set(3, 3, '#ffffff');
  return c;
}
function feather() {
  const c = new Canvas(6, 10);
  c.ellipse(3, 5, 2.4, 4.6, '#f3f0ea'); c.vline(3, 1, 9, '#9aaabf'); c.set(2, 2, '#ffffff');
  return c;
}
function ring(r, col) {
  const c = new Canvas(32, 32);
  for (let y = 0; y < 32; y++) for (let x = 0; x < 32; x++) { const d = Math.hypot(x + 0.5 - 16, y + 0.5 - 16); if (d <= r && d > r - (r > 10 ? 1.5 : 2)) c.set(x, y, col); }
  // 8 yönde kısa ışınlar (pixel art patlama hissi)
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; c.set(Math.round(16 + Math.cos(a) * (r + 2)), Math.round(16 + Math.sin(a) * (r + 2)), col); }
  return c;
}

